    aliases: ["watt", "centrifugal governor", "flyball governor"],
    relatedTerms: [],
    sources: [{ label: "The centrifugal governor was invented by Christiaan Huygens in the seventeenth century for regulating windmills and water wheels; in 1788 James Watt adapted one to control his steam engine, regulating the admission of steam into the cylinders, and the development proved important enough that Watt is sometimes called the inventor", href: "https://en.wikipedia.org/wiki/Centrifugal_governor" }, { label: "Watt designed his centrifugal governor in 1788 to regulate the angular velocity of the steam engine; the first mathematical paper on feedback was published by James Clerk Maxwell in 1868, and Minorsky's later work on the derivative of the error supported the emergence of proportional-integral-derivative control", href: "https://arxiv.org/pdf/1801.08806" }],
