    domains: ["enterprise-networking"],
    aliases: ["baird", "television", "frith street"],
    relatedTerms: [],
    sources: [{ label: "Baird's demonstration to members of the Royal Institution on the evening of 26 January 1926: none of the attending members published any comment, suggesting they had not recognised the significance; the only first-hand report appeared in The Times two days later as a minor event, and in April 1926 a prospective investor concluded it would be an error of judgment to place the equipment on the market", href: "https://theconversation.com/a-century-ago-john-logie-baird-achieved-a-landmark-moment-in-television-history-the-viewers-werent-convinced-274089" }, { label: "Baird was the first to achieve easily discernible images; in 1928 he made the first overseas broadcast from London to New York over telephone lines and demonstrated colour television; in 1932 RCA demonstrated all-electronic television using a cathode ray tube and Zworykin's iconoscope camera tube, greatly improving picture quality", href: "https://www.history.com/this-day-in-history/january-26/baird-demonstrates-tv" }],
