    relatedTerms: [],
    sources: [{ label: "Engineering and Technology History Wiki: Weston, born in Shropshire in 1850, encountered great difficulty making electrical measurements with the clumsy and slow instruments then available, so he developed and built a set of more practical instruments for his own experiments; these were so successful that in 1888 he abandoned his other interests and founded the Weston Electrical Instrument Company; his standard cell became the universal standard of electromotive force in 1908", href: "https://ethw.org/Edward_Weston" }, { label: "IEEE milestone, Weston Meters 1887-1893: the first portable and direct-reading current and voltage meters, enabled by the first truly permanent magnets, temperature-insensitive conductors, low-resistance non-magnetic springs, metal coil frames whose induced eddy currents damped the pointer, the electric shunt of 1893 for large currents, and multiple ranges in a single meter", href: "https://ethw.org/Milestones:Weston_Meters,_1887-1893" }, { label: "The Weston cell, invented 1893, adopted as the International Standard for electromotive force from 1911 until superseded by the Josephson voltage standard in 1990", href: "https://en.wikipedia.org/wiki/Weston_cell" }],
