    personField: "internet",
    domains: ["enterprise-networking"],
    aliases: ["murai", "junet", "wide project", "internet samurai"],
    relatedTerms: [],
    sources: [{ label: "Internet Hall of Fame: known as the father of the Internet in Japan and, outside Japan, as the Internet samurai; in 1984 he developed JUNET, the first inter-university network in the country, and in 1988 founded the WIDE Project", href: "https://www.internethalloffame.org/inductee/jun-murai/" }, { label: "Asia Internet History: Murai initiated the WIDE project in 1987 as a joint project between universities and industrial research laboratories, the first true Internet in Japan using TCP/IP over leased lines, with an international link to the US established through Hawaii with substantial help from Toben Nielsen at the University of Hawaii", href: "https://sites.google.com/site/internethistoryasia/book1/2--THE-INTERNET-IN-1980s" }],
